const base=curatedNames.map((x,i)=>{let id='ELC-'+String(x[2]).padStart(3,'0');return{id,name:x[0],cat:x[1],image:'assets/store-products/'+id+'.jpg',source:'متجر إلكترونيات متخصص',active:i%7!==6,qty:[12,6,8,10,2,9,7,5][i%8],reserved:i%4,loaned:i%5===0?2:i%3===0?1:0,max:Math.min(3,[12,6,8,10,2,9,7,5][i%8]),location:String.fromCharCode(65+(i%6))+'-'+String(1+(i%12)).padStart(2,'0'),desc:'قطعة كهربائية أصلية مخصصة للمشاريع والتجارب العملية داخل المعمل.',uses:180-i*2,custom:false}});
const storedInventory=JSON.parse(localStorage.getItem('tuwaiq_inventory')||'[]');
let inventory=base.map(b=>({...b,...(storedInventory.find(s=>s.id===b.id)||{}),image:b.image,source:b.source})).concat(storedInventory.filter(s=>s.custom));
let cart=JSON.parse(localStorage.getItem('tuwaiq_cart')||'[]');
let orders=JSON.parse(localStorage.getItem('tuwaiq_orders')||'null')||[{id:'TWQ-2048',status:'approved',date:'اليوم، ٣:٣٠ م',items:['Arduino Uno','حساس حركة PIR','طقم أسلاك Jumper']},{id:'TWQ-2013',status:'pending',date:'٢١ سبتمبر، ١٠:٠٠ ص',items:['نظارة واقع افتراضي']},{id:'TWQ-1977',status:'returned',date:'تم الإرجاع ١٢ سبتمبر',items:['ملتيميتر رقمي','عدة لحام متكاملة']}];
const ar=n=>Number(n).toLocaleString('ar-SA');
let iconFrame=0;const refreshIcons=()=>{cancelAnimationFrame(iconFrame);iconFrame=requestAnimationFrame(()=>window.lucide?.createIcons({attrs:{'stroke-width':1.8}}))};
let favorites=new Set(JSON.parse(localStorage.getItem('tuwaiq_favorites')||'[]'));
const save=()=>{localStorage.setItem('tuwaiq_inventory',JSON.stringify(inventory));localStorage.setItem('tuwaiq_cart',JSON.stringify(cart));localStorage.setItem('tuwaiq_orders',JSON.stringify(orders))};
function sprite(it,cls=''){if(it.image)return `<div class="photo ${cls}"><img src="${it.image}" alt="${it.name}" loading="lazy" decoding="async"></div>`;return `<div class="photo ${cls}"></div>`}
function product(it){let avail=Math.max(0,it.qty-it.reserved-it.loaned),state=avail===0?['off','غير متاح']:avail<=2?['low','كمية محدودة']:['available','متوفر'];return `<article class="product">${sprite(it)}<button class="favorite ${favorites.has(it.id)?'active':''}" aria-label="${favorites.has(it.id)?'إزالة من':'إضافة إلى'} المفضلة" onclick="toggleFavorite('${it.id}',event)"><i data-lucide="heart"></i></button><span class="badge ${state[0]}">${state[1]}</span><h3>${it.name}</h3><div class="meta">${it.cat} · ${it.id}</div><div class="productfoot"><span class="meta">المتاح: <b>${ar(avail)}</b></span><button class="add" aria-label="إضافة ${it.name}" ${avail?'':'disabled'} onclick="addCart('${it.id}')"><i data-lucide="plus"></i></button></div><button class="wide secondary btn detailsbtn" onclick="showDetail('${it.id}')"><i data-lucide="eye"></i> التفاصيل</button></article>`}
function init(){installBrandLogo();fillSelects();installCatalogTools();renderHome();renderCatalog();renderOrders();renderAdmin();updateCart();refreshIcons();}
function installBrandLogo(){let mark=document.querySelector('.brand b');if(!mark)return;mark.innerHTML='<img src="assets/tuwaiq-academy-logo.svg" alt="شعار أكاديمية طويق" width="48" height="48">';mark.classList.add('academy-logo')}
function fillSelects(){let opts='<option value="all">كل الفئات</option>'+cats.map(c=>`<option value="${c[0]}">${c[0]}</option>`).join('');catFilter.innerHTML=opts;adminCat.innerHTML=opts;newCat.innerHTML=cats.map(c=>`<option>${c[0]}</option>`).join('');catRail.innerHTML='<button class="active" onclick="pickCat(\'all\',this)">الكل</button>'+cats.map(c=>`<button onclick="pickCat('${c[0]}',this)">${c[1]} ${c[0]}</button>`).join('')}
function renderHome(){homeCategories.innerHTML=cats.map(c=>`<button class="category" onclick="filterCat('${c[0]}')"><b><i data-lucide="${c[1]}"></i></b>${c[0]}<small>${ar(inventory.filter(i=>i.cat===c[0]).length)} صنف</small></button>`).join('');popularGrid.innerHTML=inventory.filter(i=>i.active).sort((a,b)=>b.uses-a.uses).slice(0,4).map(product).join('');refreshIcons()}
function go(id){document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));document.getElementById(id).classList.add('active');document.querySelectorAll('header nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===id));if(id==='catalog')renderCatalog();if(id==='orders')renderOrders();refreshIcons();scrollTo({top:0,behavior:'smooth'})}
function homeToCatalog(){go('catalog');catalogSearch.value=homeSearch.value;renderCatalog()}function filterCat(c){go('catalog');catFilter.value=c;renderCatalog()}function pickCat(c,b){catFilter.value=c;document.querySelectorAll('.catrail button').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderCatalog()}function resetFilters(){catalogSearch.value='';catFilter.value='all';stockFilter.value='all';if(document.getElementById('sortCatalog'))sortCatalog.value='popular';document.getElementById('favoriteOnly')?.classList.remove('active');renderCatalog()}
function filtered(admin=false){let q=(admin?adminSearch:catalogSearch).value.trim().toLowerCase(),cat=(admin?adminCat:catFilter).value,status=admin?adminStatus.value:stockFilter.value;return inventory.filter(i=>(admin||i.active)&&(!q||(i.name+' '+i.id).toLowerCase().includes(q))&&(cat==='all'||i.cat===cat)&&(status==='all'||status==='active'&&i.active||status==='inactive'&&!i.active||status==='available'&&i.qty-i.reserved-i.loaned>2||status==='low'&&i.active&&i.qty-i.reserved-i.loaned<=2))}
function installCatalogTools(){let filters=document.querySelector('#catalog .filters');if(document.getElementById('sortCatalog'))return;filters.insertAdjacentHTML('beforeend',`<select id="sortCatalog" onchange="renderCatalog()" aria-label="ترتيب القطع"><option value="popular">الأكثر استخدامًا</option><option value="available">الأكثر توفرًا</option><option value="name">الاسم أبجديًا</option></select><button id="favoriteOnly" class="filtertoggle" onclick="toggleFavoriteFilter()"><i data-lucide="heart"></i> المفضلة فقط</button>`)}
function renderCatalog(){let rows=filtered();if(document.getElementById('favoriteOnly')?.classList.contains('active'))rows=rows.filter(i=>favorites.has(i.id));let sort=document.getElementById('sortCatalog')?.value||'popular';rows.sort((a,b)=>sort==='available'?(b.qty-b.reserved-b.loaned)-(a.qty-a.reserved-a.loaned):sort==='name'?a.name.localeCompare(b.name,'ar'):b.uses-a.uses);catalogGrid.innerHTML=rows.map(product).join('');catalogCount.textContent=`${ar(rows.length)} صنف ظاهر ضمن ${ar(cats.length)} فئات`;catalogEmpty.classList.toggle('hidden',rows.length>0);refreshIcons()}
function toggleFavorite(id,event){event?.stopPropagation();favorites.has(id)?favorites.delete(id):favorites.add(id);localStorage.setItem('tuwaiq_favorites',JSON.stringify([...favorites]));renderCatalog();renderHome();toast(favorites.has(id)?'تمت الإضافة إلى المفضلة':'تمت الإزالة من المفضلة')}
function toggleFavoriteFilter(){document.getElementById('favoriteOnly').classList.toggle('active');renderCatalog()}
function showDetail(id){let i=inventory.find(x=>x.id===id),avail=i.qty-i.reserved-i.loaned;itemDetail.innerHTML=`<div class="detailtop">${sprite(i)}<div><span class="badge ${avail>2?'available':avail?'low':'off'}">${avail?'متوفر':'غير متاح'}</span><h2>${i.name}</h2><p>${i.desc}</p><div class="meta">الرقم: ${i.id}<br>الموقع: ${i.location}<br>الحد الأعلى: ${ar(i.max)} قطع<br>المتاح الآن: ${ar(Math.max(0,avail))}<br>مصدر الصورة: ${i.custom?'رفع المشرف':'متجر إلكترونيات متخصص'}</div><button class="btn primary wide" style="margin-top:18px" onclick="addCart('${id}');closeOverlay('detail')"><i data-lucide="shopping-bag"></i> إضافة إلى السلة</button></div></div>`;openOverlay('detail')}
function addCart(id){let it=inventory.find(i=>i.id===id);if(!it)return toast('تعذر العثور على هذه القطعة');let row=cart.find(c=>c.id===id),avail=it.qty-it.reserved-it.loaned;if(!it.active||avail<1)return toast('هذه القطعة غير متاحة حالياً');if(row){if(row.qty>=Math.min(avail,it.max))return toast('وصلت للحد الأعلى المتاح');row.qty++}else cart.push({id,qty:1});save();updateCart();toast('تمت إضافة القطعة إلى السلة')}
function updateCart(){cart=cart.filter(c=>inventory.some(i=>i.id===c.id)&&c.qty>0);let n=cart.reduce((s,x)=>s+x.qty,0);cartCount.textContent=cartTop.textContent=ar(n);document.querySelector('.cartfab').classList.toggle('hasitems',n>0)}function openCart(){updateCart();renderCart();let panel=document.getElementById('cart');panel.style.display='block';panel.style.visibility='visible';panel.classList.add('open');document.body.classList.add('locked');refreshIcons()}function renderCart(){cart=cart.filter(c=>inventory.some(i=>i.id===c.id)&&c.qty>0);save();if(!cart.length){cartItems.innerHTML='<div class="empty"><i data-lucide="shopping-bag"></i><h3>السلة فارغة</h3><p>اختر القطع التي تحتاجها أولاً.</p><button class="btn primary" onclick="closeOverlay(\'cart\');go(\'catalog\')"><i data-lucide="boxes"></i> تصفح القطع</button></div>';bookingForm.classList.add('hidden');refreshIcons();return}cartItems.innerHTML=cart.map(c=>{let i=inventory.find(x=>x.id===c.id);return `<div class="cartitem">${sprite(i)}<div><b>${i.name}</b><div class="meta">الحد الأعلى ${ar(i.max)}</div></div><div class="qty"><button aria-label="إنقاص" onclick="qty('${i.id}',-1)"><i data-lucide="minus"></i></button><b>${ar(c.qty)}</b><button aria-label="زيادة" onclick="qty('${i.id}',1)"><i data-lucide="plus"></i></button></div></div>`}).join('');bookingForm.classList.remove('hidden');refreshIcons()}
function qty(id,d){let c=cart.find(x=>x.id===id),i=inventory.find(x=>x.id===id);if(!c||!i){cart=cart.filter(x=>x.id!==id);save();updateCart();return renderCart()}let max=Math.min(i.max,i.qty-i.reserved-i.loaned);c.qty+=d;if(c.qty<1)cart=cart.filter(x=>x.id!==id);if(c.qty>max)c.qty=max;save();updateCart();renderCart()}
function submitBooking(){if(!terms.checked)return toast('وافق على شروط الاستخدام أولاً');let start=new Date(pickup.value),end=new Date(returnAt.value);if(!start.getTime()||!end.getTime()||end<=start)return toast('تحقق من مواعيد الاستلام والإرجاع');if(start.getHours()<8||start.getHours()>=20)return toast('الاستلام متاح بين ٨ ص و٨ م');let id='TWQ-'+(2100+orders.length);orders.unshift({id,status:'pending',date:new Date(pickup.value).toLocaleString('ar-SA'),items:cart.map(c=>inventory.find(i=>i.id===c.id).name)});cart.forEach(c=>inventory.find(i=>i.id===c.id).reserved+=c.qty);cart=[];save();updateCart();closeOverlay('cart');go('orders');toast('تم إرسال طلبك للمراجعة بنجاح')}
const statusMap={approved:['approved','تمت الموافقة'],pending:['pending','بانتظار الموافقة'],returned:['available','تم الإرجاع'],ready:['approved','جاهز للاستلام'],rejected:['rejected','مرفوض']};
function renderOrders(mode='all'){let rows=orders.filter(o=>mode==='all'||mode==='completed'&&o.status==='returned'||mode==='current'&&o.status!=='returned'&&o.status!=='rejected');userOrders.innerHTML=rows.map(o=>`<article class="order"><div class="orderthumb photo ordericon"><i data-lucide="package-check"></i></div><div><b>#${o.id}</b> <span class="badge ${statusMap[o.status][0]}">${statusMap[o.status][1]}</span><div class="meta">${o.items.join('، ')}</div><small>${o.date}</small></div><button class="btn secondary" onclick="openOrder('${o.id}')"><i data-lucide="eye"></i> عرض التفاصيل</button></article>`).join('')||'<div class="empty"><i data-lucide="inbox"></i><h3>لا توجد طلبات هنا</h3><p>ستظهر الطلبات المناسبة لهذا التصنيف.</p></div>';refreshIcons()}
function filterOrders(mode,button){document.querySelectorAll('#orders .tabs button').forEach(b=>b.classList.remove('active'));button.classList.add('active');renderOrders(mode)}
function ensureOrderModal(){let box=document.getElementById('orderDetail');if(box){window.orderDetailBody=document.getElementById('orderDetailBody');return box}document.body.insertAdjacentHTML('beforeend',`<div class="overlay" id="orderDetail" role="dialog" aria-modal="true" aria-labelledby="orderDetailTitle"><div class="modal ordermodal"><button class="close" aria-label="إغلاق" onclick="closeOverlay('orderDetail')"><i data-lucide="x"></i></button><div id="orderDetailBody"></div></div></div>`);let overlay=document.getElementById('orderDetail');window.orderDetailBody=document.getElementById('orderDetailBody');overlay.onclick=e=>{if(e.target===overlay)closeOverlay('orderDetail')};return overlay}
function openOrder(id){let o=orders.find(x=>x.id===id);if(!o)return toast('تعذر العثور على الطلب');ensureOrderModal();let status=statusMap[o.status]||['pending','بانتظار الموافقة'],returned=o.status==='returned',rejected=o.status==='rejected',approved=['approved','ready','picked','late'].includes(o.status);orderDetailBody.innerHTML=`<div class="orderdetail-head"><div class="ordericon"><i data-lucide="clipboard-list"></i></div><div><label>تفاصيل الطلب</label><h2 id="orderDetailTitle">#${o.id}</h2><span class="badge ${status[0]}">${status[1]}</span></div></div><div class="orderfacts"><div><span>تاريخ الطلب</span><b>${o.date}</b></div><div><span>عدد الأصناف</span><b>${ar(o.items.length)}</b></div><div><span>موعد الاستلام</span><b>${o.pickup||'٢٠ سبتمبر، ١٠:٠٠ ص'}</b></div><div><span>موعد الإرجاع</span><b>${o.returnAt||'٢٣ سبتمبر، ٥:٠٠ م'}</b></div></div><h3>القطع المطلوبة</h3><div class="orderitems">${o.items.map((name,index)=>`<div><span>${ar(index+1)}</span><b>${name}</b><small>الكمية: ١</small></div>`).join('')}</div><div class="timeline"><div class="done"><i data-lucide="check"></i><span><b>تم إرسال الطلب</b><small>${o.date}</small></span></div><div class="${approved||returned?'done':rejected?'failed':''}"><i data-lucide="${rejected?'x':'check'}"></i><span><b>${rejected?'تم رفض الطلب':'مراجعة المشرف'}</b><small>${rejected?'يمكنك إنشاء طلب جديد':'تم تسجيل حالة الطلب'}</small></span></div><div class="${returned?'done':''}"><i data-lucide="rotate-ccw"></i><span><b>إرجاع القطع</b><small>${returned?'تم الإرجاع بنجاح':'بانتظار اكتمال الاستعارة'}</small></span></div></div>${approved&&!returned?`<div class="qrbox"><i data-lucide="qr-code"></i><div><b>رمز الاستلام</b><small>اعرض هذا الرمز للمشرف عند الاستلام أو الإرجاع</small></div></div>`:''}<button class="btn secondary wide" onclick="closeOverlay('orderDetail')">إغلاق</button>`;openOverlay('orderDetail')}
function toggleRole(){let admin=adminArea.classList.contains('hidden');adminArea.classList.toggle('hidden',!admin);userArea.classList.toggle('hidden',admin);roleBtn.innerHTML=admin?'<i data-lucide="user-round"></i><span>واجهة المستعير</span>':'<i data-lucide="layout-dashboard"></i><span>لوحة المشرف</span>';document.querySelector('header nav').classList.toggle('hidden',admin);if(admin)renderAdmin();refreshIcons();scrollTo({top:0,behavior:'smooth'})}
function adminView(id,b){document.querySelectorAll('.adminview').forEach(x=>x.classList.remove('active'));document.getElementById('admin-'+id).classList.add('active');if(b){document.querySelectorAll('.sidebar button').forEach(x=>x.classList.remove('active'));b.classList.add('active')}if(id==='inventory')renderInventory();if(id==='requests')renderRequests();if(id==='cats')renderCats();if(id==='reports')renderReports();refreshIcons();scrollTo({top:0,behavior:'smooth'})}
function renderAdmin(){let active=inventory.filter(i=>i.active),low=active.filter(i=>i.qty-i.reserved-i.loaned<=2),units=active.reduce((s,i)=>s+i.qty,0);kpis.innerHTML=[['طلبات جديدة','٨','تحتاج مراجعة'],['قطع مفعّلة',active.length,'من '+inventory.length],['إجمالي الوحدات',units,'في المخزون'],['مخزون منخفض',low.length,'يحتاج متابعة']].map(x=>`<article class="kpi"><span>${x[0]}</span><strong>${ar(x[1])}</strong><em>${x[2]}</em></article>`).join('');requestPreview.innerHTML=orders.slice(0,3).map(o=>`<div class="reqrow"><span class="badge ${statusMap[o.status][0]}">${statusMap[o.status][1]}</span><div><b>#${o.id}</b><small class="meta">${o.items.length} قطع · ${o.date}</small></div><button class="btn secondary" onclick="approveOrder('${o.id}')">مراجعة</button></div>`).join('');categoryStats.innerHTML=cats.slice(0,6).map(c=>{let n=active.filter(i=>i.cat===c[0]).length;return `<div class="statrow"><b>${c[0]}</b><i style="--w:${Math.min(100,n*15)}%"></i><span>${ar(n)}</span></div>`}).join('')}
function renderInventory(){let rows=filtered(true);invSummary.innerHTML=`<span>النتائج <b>${ar(rows.length)}</b></span><span>مفعّل <b>${ar(rows.filter(i=>i.active).length)}</b></span><span>إجمالي الوحدات <b>${ar(rows.reduce((s,i)=>s+i.qty,0))}</b></span>`;invList.innerHTML=rows.map(i=>`<article class="invrow"><button class="switch ${i.active?'on':''}" onclick="toggleItem('${i.id}')"><i></i></button>${sprite(i)}<div><b>${i.name}</b><div class="meta">${i.id} · ${i.cat}</div></div><label>الكمية<input type="number" min="0" value="${i.qty}" onchange="editItem('${i.id}','qty',this.value)"></label><label>الموقع<input value="${i.location}" onchange="editItem('${i.id}','location',this.value)"></label><label>الحد<input type="number" min="1" value="${i.max}" onchange="editItem('${i.id}','max',this.value)"></label><button class="btn secondary" onclick="showDetail('${i.id}')">عرض</button></article>`).join('')}
function toggleItem(id){let i=inventory.find(x=>x.id===id);i.active=!i.active;save();renderInventory();renderAdmin();renderHome();renderCatalog();toast(i.active?'تمت إضافة القطعة لمخزون المعمل':'تم إخفاء القطعة من المستعيرين')}
function editItem(id,key,val){let i=inventory.find(x=>x.id===id);i[key]=key==='location'?val:Math.max(0,+val||0);if(key==='qty'&&i.max>i.qty)i.max=i.qty||1;save();renderAdmin();renderCatalog();toast('تم حفظ التعديل')}
function openAddItem(){openOverlay('addItem')}async function addCustom(e){e.preventDefault();let image='';let f=newImage.files[0];if(f)image=await new Promise(r=>{let x=new FileReader;x.onload=()=>r(x.result);x.readAsDataURL(f)});inventory.unshift({id:'LAB-C'+Date.now().toString().slice(-5),name:newName.value,cat:newCat.value,active:true,qty:+newQty.value,reserved:0,loaned:0,max:Math.max(1,Math.min(3,+newQty.value)),location:newLoc.value||'غير محدد',desc:'قطعة مخصصة تمت إضافتها بواسطة المشرف.',uses:0,custom:true,image});save();e.target.reset();closeOverlay('addItem');renderInventory();renderAdmin();renderHome();toast('تمت إضافة القطعة للمخزون')}
function renderRequests(){adminRequests.innerHTML=orders.map(o=>`<div class="reqrow"><span class="badge ${statusMap[o.status][0]}">${statusMap[o.status][1]}</span><div><b>#${o.id}</b><div class="meta">${o.items.join('، ')} · ${o.date}</div></div>${o.status==='pending'?`<button class="btn primary" onclick="approveOrder('${o.id}')">اعتماد</button><button class="btn secondary" onclick="rejectOrder('${o.id}')">رفض</button>`:`<button class="btn secondary" onclick="toast('تم تسجيل تحديث الطلب')">تحديث الحالة</button>`}</div>`).join('')}
function approveOrder(id){orders.find(o=>o.id===id).status='approved';save();renderRequests();renderAdmin();toast('تم اعتماد الطلب وإشعار المستعير')}function rejectOrder(id){orders.find(o=>o.id===id).status='rejected';save();renderRequests();toast('تم رفض الطلب')}
function renderCats(){catManager.innerHTML=cats.map(c=>`<article class="catcard"><span>${ar(inventory.filter(i=>i.cat===c[0]).length)}</span><b>${c[1]} ${c[0]}</b><p class="meta">${ar(inventory.filter(i=>i.cat===c[0]&&i.active).length)} مفعّل في المعمل</p><button class="btn secondary" onclick="adminView('inventory');adminCat.value='${c[0]}';renderInventory()">عرض القطع</button></article>`).join('')}
function renderReports(){let active=inventory.filter(i=>i.active),units=active.reduce((s,i)=>s+i.qty,0);reportKpis.innerHTML=[['الأصناف النشطة',active.length],['إجمالي الوحدات',units],['المعارة الآن',active.reduce((s,i)=>s+i.loaned,0)],['المحجوزة',active.reduce((s,i)=>s+i.reserved,0)]].map(x=>`<article class="kpi"><span>${x[0]}</span><strong>${ar(x[1])}</strong></article>`).join('');popularReport.innerHTML=active.sort((a,b)=>b.uses-a.uses).slice(0,8).map(i=>`<div class="bar"><b>${i.name}</b><i style="--w:${Math.max(10,i.uses/2)}%"></i><span>${ar(i.uses)}</span></div>`).join('')}
function exportInventory(){let rows=[['الرقم','الاسم','الفئة','مفعّل','الكمية','المحجوز','المعار','الموقع'],...inventory.map(i=>[i.id,i.name,i.cat,i.active?'نعم':'لا',i.qty,i.reserved,i.loaned,i.location])];let csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='مخزون-معمل-طويق.csv';a.click();URL.revokeObjectURL(a.href);toast('تم تصدير المخزون')}
function openOverlay(id){let el=document.getElementById(id);if(!el)return;el.style.display='block';requestAnimationFrame(()=>el.classList.add('open'));document.body.classList.add('locked');refreshIcons()}function closeOverlay(id){let el=document.getElementById(id);if(!el)return;el.classList.remove('open');setTimeout(()=>{if(!el.classList.contains('open'))el.style.display='none'},230);if(!document.querySelector('.overlay.open'))document.body.classList.remove('locked')}document.querySelectorAll('.overlay').forEach(o=>o.onclick=e=>{if(e.target===o)closeOverlay(o.id)});document.addEventListener('keydown',e=>{if(e.key==='Escape'){let o=document.querySelector('.overlay.open');if(o)closeOverlay(o.id)}});function toast(t){let x=document.getElementById('toast');x.innerHTML=`<i data-lucide="circle-check"></i><span>${t}</span>`;x.classList.add('show');refreshIcons();clearTimeout(window.to);window.to=setTimeout(()=>x.classList.remove('show'),2500)}
function renderInventorySafe(){renderInventory()}window.openAddItem=openAddItem;window.openCart=openCart;
init();
